<?php require 'config.php';require_login();if(!is_admin())exit('Administrator access only');$flights=$pdo->query('SELECT * FROM flights ORDER BY departure DESC')->fetchAll();$bookings=$pdo->query('SELECT b.*,u.name,f.flight_no FROM bookings b JOIN users u ON u.id=b.user_id JOIN flights f ON f.id=b.flight_id ORDER BY b.id DESC')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT INTO flights(airline,flight_no,origin,destination,departure,arrival,travel_class,fare,total_seats,available_seats) VALUES(?,?,?,?,?,?,?,?,?,?)');$seats=(int)$_POST['seats'];$s->execute([$_POST['airline'],$_POST['flight_no'],$_POST['origin'],$_POST['destination'],$_POST['departure'],$_POST['arrival'],$_POST['class'],$_POST['fare'],$seats,$seats]);header('Location: admin.php');exit;}?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><h1>Admin panel / reports</h1><h2>Add flight schedule</h2><form method="post" class="grid"><input name="airline" placeholder="Airline" required><input name="flight_no" placeholder="Flight number" required><input name="origin" placeholder="Origin" required><input name="destination" placeholder="Destination" required><label>Departure<input type="datetime-local" name="departure" required></label><label>Arrival<input type="datetime-local" name="arrival" required></label><select name="class"><option>Economy</option><option>Business</option><option>First</option></select><input type="number" step=".01" name="fare" placeholder="Fare" required><input type="number" name="seats" placeholder="Seats" min="1" required><button>Add flight</button></form><h2>Flight inventory</h2><table><tr><th>Flight</th><th>Route</th><th>Departure</th><th>Seats left</th></tr><?php foreach($flights as $f):?><tr><td><?=h($f['flight_no'])?></td><td><?=h($f['origin'])?> → <?=h($f['destination'])?></td><td><?=h($f['departure'])?></td><td><?=h($f['available_seats'])?></td></tr><?php endforeach;?></table><h2>Booking report</h2><table><tr><th>Code</th><th>Customer</th><th>Flight</th><th>Amount</th><th>Status</th></tr><?php foreach($bookings as $b):?><tr><td><?=h($b['booking_code'])?></td><td><?=h($b['name'])?></td><td><?=h($b['flight_no'])?></td><td>₹<?=h($b['amount'])?></td><td><?=h($b['status'])?></td></tr><?php endforeach;?></table></div></div></body></html>